import sys

def main():
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return

    n, m = data[0], data[1]
    grid = []
    idx = 2
    for _ in range(n):
        grid.append(data[idx:idx + m])
        idx += m

    cost_a = 0
    cost_b = 0

    for i in range(n):
        for j in range(m):
            g = grid[i][j] & 1
            t = (i + j) & 1
            if g != t:
                cost_a += 1
            else:
                cost_b += 1

    if cost_a <= cost_b:
        cost = cost_a
        use_a = True
    else:
        cost = cost_b
        use_a = False

    out = [str(cost)]
    for i in range(n):
        row = []
        for j in range(m):
            t = (i + j) & 1
            if not use_a:
                t = 1 - t

            v = grid[i][j]
            if (v & 1) != t:
                v += 1
            row.append(str(v))
        out.append(" ".join(row))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
